import sys; sys.path.insert(0, "tools")
from gen_lib import maker
S, M, save = maker("bc05", 505)
# ---------- QCS (60) ----------
S("definition","cytosquelette : cellules eucaryotes uniquement","Dans quels types de cellules le cytosquelette est-il présent ?","Uniquement dans les cellules eucaryotes",["Dans toutes les cellules","Uniquement chez les procaryotes","Uniquement dans les cellules végétales"],"Il donne leur forme aux cellules et permet les mouvements cellulaires.",3)
S("definition","rôles du cytosquelette","Quels sont les rôles du cytosquelette ?","Donner leur forme aux cellules, permettre les mouvements cellulaires et intervenir dans la division cellulaire",["Synthétiser l’énergie, stocker l’information génétique et digérer les déchets","Transporter les ions, fabriquer les lipides et dégrader les protéines","Produire l’oxygène, fixer le carbone et protéger le noyau"],"Le cytosquelette est formé de trois types de filaments.",3)
S("definition","trois types de filaments","Quels sont les trois types de filaments du cytosquelette ?","Les microtubules, les microfilaments d’actine et les filaments intermédiaires",["Les microtubules, les lamines et la kératine","L’actine, la tubuline et la myosine","Les histones, les microtubules et l’actine"],"Ce sont tous des filaments protéiques.",4)
S("identification","microtubules : rayonnent à partir du noyau","Quels filaments rayonnent à partir du noyau ?","Les microtubules",["Les microfilaments d’actine","Les filaments intermédiaires","Les lamines uniquement"],"Les microtubules contrôlent également les mouvements cellulaires.",4)
S("identification","microfilaments : longent la membrane plasmique","Quels filaments longent la membrane plasmique et contrôlent les mouvements associés aux membranes ?","Les microfilaments d’actine",["Les microtubules","Les filaments intermédiaires","Les histones"],"Les filaments intermédiaires protègent les cellules des contraintes externes.",4)
S("definition","filaments intermédiaires : contraintes externes","Quelle est la fonction principale des filaments intermédiaires ?","Protéger les cellules des contraintes externes",["Permettre les mouvements associés aux membranes","Nucléer les microtubules","Faire glisser les filaments d’actine"],"Ils forment par exemple une corbeille autour du noyau.",4)
S("definition","monomères associés de façon non covalente","Comment les monomères des filaments du cytosquelette sont-ils associés entre eux ?","Par des associations non covalentes",["Par des liaisons covalentes","Par des ponts disulfure","Par des liaisons peptidiques"],"Il existe des phénomènes d’association et de dissociation des monomères.",6)
S("definition","visualisation par immunocytochimie","Comment visualise-t-on facilement le cytosquelette ?","En microscopie optique à fluorescence, par immunocytochimie avec des anticorps marqués par un fluorochrome",["En microscopie électronique à balayage sans marquage","Par coloration de Gram","Par chromatographie"],"Les phénomènes d’association/dissociation expliquent la dynamique du cytosquelette.",6)
S("identification","microtubules absents des globules rouges","Dans quelles cellules eucaryotes les microtubules sont-ils absents ?","Les globules rouges",["Les neurones","Les hépatocytes","Les cellules musculaires"],"Les microtubules sont présents dans toutes les cellules eucaryotes sauf les globules rouges.",10)
S("definition","microtubules : tubes creux de tubuline","Que sont les microtubules ?","Des tubes creux formés par un assemblage de tubuline",["Des filaments pleins d’actine","Des fibres de kératine","Des chaînes de lamines"],"Les tubulines s’associent de façon non covalente.",10)
S("definition","tubuline : hétérodimère alpha/bêta","Comment est constituée la tubuline ?","D’un hétérodimère de deux protéines globulaires : la tubuline α et la tubuline β",["D’un monomère unique","D’un trimère de tubulines α, β et γ","D’une protéine fibreuse unique"],"Les tubulines s’associent pour former les protofilaments.",10)
S("definition","polarité des microtubules","Que signifie la polarité d’un microtubule ?","Ses deux extrémités ne sont pas équivalentes : une extrémité + et une extrémité −",["Ses deux extrémités sont identiques","Il possède deux extrémités +","Il est chargé électriquement"],"On parle de polarité.",11)
S("definition","formation des microtubules in vitro","Quels éléments permettent la formation d’un microtubule in vitro ?","Une solution concentrée de tubuline α et β, de Mg²⁺ (magnésium) et de GTP (guanosine triphosphate)",["De l’ATP (adénosine triphosphate) seul","De l’acide désoxyribonucléique","Des lipides"],"On observe une phase de nucléation suivie d’une phase de croissance.",12)
S("chiffre","extrémité + : croissance 5 fois plus rapide","Quelle extrémité d’un microtubule s’allonge environ 5 fois plus vite ?","L’extrémité +",["L’extrémité −","Les deux à la même vitesse","Aucune des deux"],"Une extrémité s’allonge 5 fois plus vite que l’autre.",13)
S("definition","définition de l’extrémité +","Comment définit-on l’extrémité + d’un microtubule ?","Comme l’extrémité à croissance rapide",["Comme l’extrémité fixée au centrosome","Comme l’extrémité qui ne s’allonge jamais","Comme l’extrémité stabilisée par le centre organisateur des microtubules"],"L’autre extrémité est définie comme l’extrémité −.",13)
S("definition","extrémité − associée au COMT","À quoi l’extrémité − des microtubules est-elle associée in vivo ?","Au centre organisateur des microtubules (COMT), c’est-à-dire au centrosome",["À la membrane plasmique","Au nucléole","Aux protéines de coiffage"],"Le centrosome est le site principal de nucléation des microtubules dans les cellules animales.",14)
S("definition","centrosome : deux centrioles et matrice","De quoi le centrosome est-il constitué ?","De deux centrioles noyés dans une masse amorphe, la matrice centrosomique",["D’un nucléole et de ribosomes","De piles de saccules","De deux noyaux"],"C’est à partir de la matrice centrosomique qu’a lieu la nucléation des microtubules.",14)
S("definition","nucléation depuis la matrice centrosomique","D’où part la nucléation des microtubules ?","De la matrice centrosomique",["De la membrane plasmique","Du noyau","Du Golgi"],"Elle a lieu dans le centrosome.",14)
S("definition","instabilité dynamique","Qu’est-ce que l’instabilité dynamique des microtubules ?","Une polymérisation et une dépolymérisation sans cesse renouvelées",["Une stabilité totale","Une dégradation définitive","Une synthèse d’acide ribonucléique"],"Elle joue un rôle majeur dans de nombreux processus physiologiques comme la morphogenèse cellulaire.",16)
S("definition","extrémités + stabilisées par protéines de coiffage","Par quoi les extrémités + des microtubules sont-elles stabilisées ?","Des protéines de coiffage fixées à la membrane plasmique",["Le centre organisateur des microtubules","Les histones","Les lamines"],"Les extrémités − sont stabilisées par le centre organisateur des microtubules.",16)
S("definition","coiffage : orientation de la croissance","Que permet la stabilisation des extrémités + par des protéines de coiffage ?","Orienter la croissance des microtubules dans une direction de la cellule et participer à sa forme",["Dégrader les microtubules","Fixer le noyau","Produire de l’énergie"],"Cela participe à la forme de la cellule in vivo.",16)
S("definition","MAP : stabilisation et déstabilisation","Que peuvent faire les MAP (Microtubule-Associated Proteins) en se liant aux microtubules ?","Les stabiliser ou les déstabiliser",["Dégrader le noyau","Fabriquer des lipides","Remplacer l’actine"],"Elles interviennent aussi dans des interactions avec d’autres composants cellulaires.",17)
S("definition","déplacement d’organites : énergie de l’ATP","Que requiert le déplacement d’organites le long des microtubules par les MAP (Microtubule-Associated Proteins) ?","De l’énergie, sous forme d’ATP (adénosine triphosphate)",["Du calcium seul","De la lumière","Aucune énergie"],"Les MAP permettent le déplacement d’organites le long des microtubules.",17)
S("definition","dynéine : vers l’extrémité −","Vers quelle extrémité des microtubules la dynéine transporte-t-elle les organites ?","L’extrémité −",["L’extrémité +","Le noyau uniquement","La membrane uniquement"],"La kinésine transporte vers l’extrémité +.",18)
S("definition","kinésine : extrémité +, mitose et méiose","Dans quels contextes la kinésine est-elle impliquée ?","Le transport vers l’extrémité + (ex. axone), la mitose et la méiose",["Le transport vers l’extrémité − uniquement","La phagocytose","La contraction musculaire"],"La kinésine et la dynéine sont des protéines associées aux microtubules (MAP) cytoplasmiques.",18)
S("cas_pratique","vésicules synaptiques le long d’un microtubule","Comment les vésicules synaptiques se déplacent-elles dans l’axone d’une cellule nerveuse ?","Le long d’un microtubule",["Le long de filaments de kératine","Le long de lamines","Par diffusion libre"],"Exemple du cours : déplacement des vésicules synaptiques le long d’un microtubule constituant l’axone.",19)
S("chiffre","cils : 10⁹ par cm²","Combien de cils par cm² se trouvent au pôle apical des cellules épithéliales du tractus respiratoire humain ?","Environ 10⁹",["Environ 10³","Environ 10⁶","Environ 10¹⁵"],"Les microtubules sont essentiels au fonctionnement des cils et des flagelles.",20)
S("cas_pratique","cils respiratoires : mucus et poussières","Que font les cils du tractus respiratoire ?","Ils font remonter le mucus avec les poussières piégées et les cellules mortes jusqu’à la bouche",["Ils propulsent les spermatozoïdes","Ils synthétisent le mucus","Ils absorbent les nutriments"],"Les poussières et cellules mortes sont ensuite avalées et éliminées.",20)
S("chiffre","microfilaments d’actine : 8 nm","Quelle est la largeur d’un microfilament d’actine ?","8 nm",["25 nm","80 nm","0,8 nm"],"Les filaments intermédiaires mesurent entre 8 et 10 nm.",24)
S("definition","actine F : hélice d’actine G","Comment est constitué un microfilament d’actine ?","D’une hélice serrée (actine F) formée de molécules d’actine globulaire (actine G)",["D’un tube creux de tubuline","D’un cordage de protéines fibreuses","D’une chaîne de lamines"],"L’actine G pèse 42 000 Da.",24)
S("definition","polarité des microfilaments d’actine","Quelles caractéristiques ont les deux extrémités d’un microfilament d’actine ?","Une extrémité − à croissance lente et une extrémité + à croissance rapide",["Deux extrémités identiques","Deux extrémités à croissance lente","Aucune polarité"],"Les microfilaments d’actine sont des structures polarisées.",24)
S("ordre","phases de la polymérisation de l’actine","Quelles phases suit la polymérisation de l’actine ?","Latence, nucléation, puis croissance",["Croissance, nucléation, puis latence","Nucléation, latence, puis dépolymérisation","Latence, puis dépolymérisation"],"L’instabilité dynamique de l’actine correspond à un mouvement de « tapis roulant ».",25)
S("definition","tapis roulant de l’actine","À quoi correspond le « tapis roulant » (treadmilling) de l’actine ?","Au déplacement d’une molécule d’actine de l’extrémité + vers l’extrémité −",["Au déplacement de l’extrémité − vers l’extrémité +","À la fusion de deux filaments","À la dégradation lysosomale"],"Les microfilaments d’actine sont essentiels au système de contraction des cellules musculaires.",26)
S("definition","actine et contraction musculaire","Dans quelles cellules les microfilaments d’actine sont-ils des composants essentiels du système de contraction ?","Les cellules musculaires",["Les hématies","Les cellules sans noyau","Les cellules procaryotes"],"Le mouvement de tapis roulant est lié à l’instabilité dynamique.",26)
S("definition","protéines de coiffage de l’actine : extrémité +","Où se situent toujours les protéines de coiffage des filaments d’actine ?","À l’extrémité +, souvent au niveau de la membrane plasmique",["À l’extrémité −","Au centre du filament","Dans le noyau"],"Elles contrôlent l’assemblage des filaments d’actine au niveau de la membrane.",27)
S("definition","filamine","Que fait la filamine ?","Elle relie deux microfilaments d’actine perpendiculaires pour former un réseau résistant aux chocs",["Elle relie deux microfilaments parallèles","Elle fragmente l’actine","Elle déplace les organites"],"Exemple du cours : la ceinture de sécurité.",28)
S("definition","fasciculine","Que fait la fasciculine ?","Elle associe deux microfilaments d’actine parallèles",["Elle associe deux microfilaments perpendiculaires","Elle fragmente l’actine","Elle fixe le noyau"],"La filamine relie des filaments perpendiculaires.",28)
S("definition","protéines d’ancrage","Que relient les protéines d’ancrage de l’actine ?","Les microfilaments d’actine à la membrane plasmique, via des protéines intrinsèques transmembranaires",["Les microtubules au noyau","Les filaments intermédiaires aux lysosomes","Les microfilaments aux mitochondries"],"Elles renforcent la membrane et peuvent tirer sur la membrane plasmique.",30)
S("definition","gelsoline : fragmentation","Quelle protéine fragmente les filaments d’actine ?","La gelsoline",["La profiline","La thymosine","La myosine"],"Les protéines de fragmentation décomposent les filaments d’actine.",31)
S("definition","profiline : stimule la polymérisation","Que fait la profiline ?","Elle se fixe à l’actine G et stimule la polymérisation à l’extrémité +",["Elle fragmente les filaments","Elle séquestre l’actine G et inhibe la polymérisation","Elle déplace les organites"],"Le complexe formé s’appelle la profilactine.",31)
S("definition","thymosine : séquestration","Que fait la thymosine ?","Elle séquestre l’actine G liée à l’ATP (adénosine triphosphate) et inhibe la polymérisation",["Elle stimule la polymérisation","Elle fragmente l’actine","Elle relie les filaments"],"C’est une protéine de rétention.",31)
S("definition","myosines : ATPases","Que sont les myosines cytoplasmiques ?","Des ATPases qui utilisent l’énergie de l’ATP (adénosine triphosphate) pour provoquer le mouvement",["Des kinases","Des phosphatases","Des protéines de coiffage"],"Il existe des myosines de type I et de type II.",32)
S("definition","myosine II : 2 têtes et une queue","Comment est constituée une myosine de type II ?","De 2 têtes motrices (ATPase) et d’une queue",["D’une tête et d’une queue courte","D’aucune tête","De 3 queues"],"La queue s’associe à d’autres molécules de myosine.",32)
S("definition","myosine II : déplacement vers l’extrémité +","Vers quelle extrémité du filament d’actine les têtes de myosine II se déplacent-elles ?","L’extrémité +",["L’extrémité −","Le centre du filament","Le noyau"],"Le mouvement est permis par l’hydrolyse de l’énergie stockée.",32)
S("ordre","trois étapes de la migration cellulaire","Quelles sont les trois étapes de la migration des cellules animales dépendantes de l’actine ?","Protrusion, attachement, traction",["Traction, protrusion, division","Attachement, division, fusion","Protrusion, fusion, apoptose"],"Lors de la protrusion, les lamellipodes s’étendent en avant de la cellule.",35)
S("cas_pratique","calcium et gelsoline","Quel ion active la gelsoline lors de la phagocytose ?","Le calcium (Ca²⁺)",["Le sodium","Le magnésium","Le potassium"],"Des signaux cellulaires augmentent la concentration locale en calcium.",36)
S("definition","gelsoline : transition gel-sol","Que provoque la gelsoline lors de la phagocytose ?","Une transition gel-sol : fragmentation puis dépolymérisation de l’actine",["Une polymérisation rapide de l’actine","Une fusion des vésicules","Une dégradation du noyau"],"Le cytosquelette se reconstitue ensuite différemment.",36)
S("definition","pseudopodes : entourer la bactérie","Que forme le cytosquelette lors de la phagocytose après sa reconstitution ?","Des pseudopodes qui s’allongent jusqu’à entourer complètement la bactérie",["Des cils","Des flagelles","Des microvillosités"],"Les pseudopodes sont des extensions cytoplasmiques.",36)
S("definition","microvillosités : surface d’échange","À quoi servent les microvillosités ?","À augmenter la surface d’échange de la cellule",["À la division cellulaire","À la contraction","À la sécrétion de mucus"],"Les microvillosités sont constituées de faisceaux de microfilaments d’actine.",37)
S("definition","microvillosités : muqueuse intestinale","Où se trouvent les microvillosités citées dans le cours ?","Au niveau des cellules épithéliales de la muqueuse intestinale",["Dans les neurones","Dans les hématies","Dans le muscle"],"Elles servent à l’absorption des nutriments.",37)
S("chiffre","filaments intermédiaires : 8 à 10 nm","Quel est le diamètre des filaments intermédiaires ?","Entre 8 et 10 nm",["25 nm","80 nm","1 nm"],"Ce sont des fibres résistantes et stables.",40)
S("definition","corbeille autour du noyau","Quel rôle jouent les filaments intermédiaires autour du noyau ?","Ils forment une « corbeille » qui le protège des chocs mécaniques",["Ils le dupliquent","Ils le dissolvent","Ils le déplacent"],"Ils sont présents dans la plupart des cellules eucaryotes.",40)
S("definition","monomères des filaments intermédiaires : protéines fibreuses","Que sont les monomères des filaments intermédiaires, à la différence des microtubules et des microfilaments ?","Des protéines fibreuses avec un domaine central commun",["Des protéines globulaires","Des lipides","Des sucres"],"Ils sont organisés en cordage.",41)
S("identification","kératines : type I","Quels filaments intermédiaires sont présents dans tous les épithéliums et les dérivés épidermiques (cheveux, ongles) ?","Les kératines (type I)",["La desmine (type II)","Les neurofilaments (type III)","Les lamines (type IV)"],"Il existe quatre classes de filaments intermédiaires.",42)
S("identification","desmine : cellules musculaires","Dans quelles cellules trouve-t-on la desmine ?","Les cellules musculaires",["Les neurones","Les épithéliums","Les hématies"],"La desmine correspond aux filaments de type II.",42)
S("identification","lamines : réseau autour du noyau","Quels filaments intermédiaires forment un réseau autour du noyau ?","Les lamines (type IV)",["Les kératines (type I)","La desmine (type II)","Les neurofilaments (type III)"],"Les lamines sont les filaments de type IV.",42)
S("definition","jonctions communicantes (gap)","Par quelles jonctions les cellules proches échangent-elles des signaux à courte distance, sans sécrétion ?","Les jonctions communicantes (gap)",["Les desmosomes","Les synapses","Les pores nucléaires"],"La signalisation peut aussi passer par des molécules d’adhérence.",46)
S("definition","communication autocrine","Quel type de signalisation agit sur la cellule émettrice ?","La signalisation autocrine",["La signalisation paracrine","La signalisation endocrine","La signalisation neuronale"],"Le médiateur local passe par le milieu extracellulaire : facteurs de croissance, cytokines.",51)
S("definition","communication endocrine : sang","Quelle signalisation passe par une sécrétion dans le courant sanguin, avec action lente ?","La signalisation endocrine",["La signalisation paracrine","La signalisation autocrine","La signalisation neuronale"],"Exemple : les hormones ; la concentration est faible (< 10⁻⁸ mol).",52)
S("definition","communication neuronale : rapide","Quelle signalisation est très rapide (millisecondes) et utilise des neurotransmetteurs à une synapse chimique ?","La signalisation neuronale (synaptique)",["La signalisation endocrine","La signalisation paracrine","La signalisation autocrine"],"Exemple : l’acétylcholine ; la concentration est haute (> 10⁻⁴ mol).",53)

